package policy; import core.*;import java.util.List; public final class CsvPolicyParser{public FirewallRule parseLine(String line){List<String> c=CsvUtil.parseLine(line);if(c.size()<6)return null;FirewallRule r=new FirewallRule();r.chain(c.get(0).toUpperCase());r.action(c.get(1).toUpperCase());r.protocol(c.get(2).toLowerCase());r.source(c.get(3));r.destination(c.get(4));r.destinationPort(PortRange.parse(c.get(5)));return r;}}
